/* Retro Bench data: Texas Instruments (TI-99/4 and TI-99/4A). Edit by hand. */
Object.assign(RCS.terms, {
  cru: {
    term: 'CRU (Communications Register Unit)',
    short: 'The TI-99 serial bit bus for keyboard, cassette and timer.',
    long: 'The 9900 reads and writes single bits on the CRU, not on the data bus. The TMS9901 answers CRU addresses for the keyboard, cassette and interrupts. A fault here shows as a dead key or a stuck interrupt, not as a dead CPU.',
  },
  grom: {
    term: 'GROM (Graphics ROM)',
    short: 'Serial ROM that holds the TI BASIC and title screen code.',
    long: 'A TI quirk: a GROM is read one byte at a time through a port and an address counter, not on the address bus. The console has three GROMs. Without them the console boots to nothing or garbled graphics.',
  },
});

/* Source documents, all on whtech.com. Page anchors are PDF pages, not printed page numbers. */
const TI_WHT = 'https://ftp.whtech.com/datasheets%20and%20manuals/';
const TI_TD = p => `${TI_WHT}Hardware/Texas%20Instruments/TI-994A%20Console%20and%20Perhipheral%20Expansion%20System%20Technical%20Data%201049717-2%20(1983).pdf#page=${p}`;
const TI_SM = p => `${TI_WHT}Hardware/Texas%20Instruments/TI994A_HC_Servicing_Manual_Oct_1983.pdf#page=${p}`;
